<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {changeState} from '../payChanges'
import type {PayRule} from '../payrollTypes'
import type {PayChange,PayChangeImpact} from '../payChanges'
import {storeToday} from '../time'
const props=defineProps<{rows:PayChange[];companyId:string;month:string;headOffice:boolean;salaryAccess:boolean;templateAccess:boolean;disabled?:boolean}>(),emit=defineEmits<{updated:[request:PayChange];locked:[value:boolean]}>()
const {api,english,current,message,issue}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
interface Item {requestId:string;commandId:string;expectedRevision:number;expectedHash:string;action:string;note:string}
interface Result {requestId:string;commandId:string;outcome:string;request:PayChange|null;errorCode:string|null;httpStatus:number}
const selected=ref<string[]>([]),note=ref(''),pending=ref<Item[]>([]),results=ref<Result[]>([]),busy=ref(false),error=ref(''),impacts=ref<Record<string,PayChangeImpact>>({}),sort=ref('risk');let generation=0
onBeforeUnmount(()=>{generation++})
watch(()=>[props.companyId,props.month],()=>{generation++;selected.value=[];pending.value=[];results.value=[];impacts.value={};note.value='';error.value='';busy.value=false})
const allowed=(r:PayChange)=>props.headOffice&&(r.adoptionId?props.templateAccess:props.salaryAccess)
function newDeduction(before:PayRule['items'],after:PayRule['items']){return after.some(a=>a.kind==='deduction'&&!before.some(b=>b.kind==='deduction'&&(a.itemId?b.itemId===a.itemId:b.label===a.label)))}
function risks(r:PayChange){const tags:string[]=[];const i=impacts.value[r.id];if(!r.adoptionId&&(i?.standardDifference!=null&&Number(i.standardDifference)<0||r.content.beforeProfile?.rule&&r.content.profile?.rule&&r.content.beforeProfile.rule.basis===r.content.profile.rule.basis&&Number(r.content.profile.rule.rate)<Number(r.content.beforeProfile.rule.rate)))tags.push(x('标准减薪','Standard pay reduction'));if(newDeduction(r.content.beforeProfile?.rule?.items||r.content.adoption?.rule.items||[],r.content.profile?.rule?.items||r.content.derivedRule?.items||[])||r.content.months.some(m=>newDeduction(m.before.items,m.after.items)))tags.push(x('新增扣款','New deduction'));if(r.effectiveDate<storeToday())tags.push(x('追溯日期','Retroactive date'));return tags}
const sorted=computed(()=>[...props.rows].sort((a,b)=>{if(sort.value==='absolute'||sort.value==='percent'){const key=sort.value==='absolute'?'standardDifference':'standardPercent',av=impacts.value[a.id]?.[key],bv=impacts.value[b.id]?.[key];if(av==null)return bv==null?0:1;if(bv==null)return -1;return Math.abs(Number(bv))-Math.abs(Number(av))}return risks(b).length-risks(a).length}))
function choose(id:string,checked:boolean){if(checked&&selected.value.length>=100){error.value=x('每次最多选择100份申请。','Select at most 100 requests.');return}selected.value=checked?[...new Set([...selected.value,id])]:selected.value.filter(v=>v!==id)}
async function execute(items:Item[]){if(busy.value||props.disabled)return;const rev=generation;busy.value=true;emit('locked',true);error.value='';pending.value=items;try{const response=await api().put<{results:Result[]}>('/pay-change-bulk-actions',{companyId:props.companyId,month:props.month||null,items});if(!current()||rev!==generation)return;results.value=[...results.value.filter(r=>!items.some(i=>i.commandId===r.commandId)),...response.results];pending.value=items.filter(i=>!response.results.some(r=>r.commandId===i.commandId&&r.outcome==='success'));for(const r of response.results){if(r.request)emit('updated',r.request);if(r.outcome==='success')selected.value=selected.value.filter(id=>id!==r.requestId)}}catch(e){if(current()&&rev===generation)error.value=message(e)}finally{if(rev===generation){busy.value=false;emit('locked',!!error.value)}}}
function start(action:string){if(props.disabled||!note.value.trim()||pending.value.length)return;const items=props.rows.filter(r=>selected.value.includes(r.id)&&allowed(r)&&r.status==='submitted').slice(0,100).map(r=>({requestId:r.id,commandId:crypto.randomUUID(),expectedRevision:r.revision,expectedHash:r.hash,action,note:note.value.trim()}));if(items.length)void execute(items)}
async function estimate(){if(props.disabled||busy.value||pending.value.length||!props.month)return;const rev=generation;busy.value=true;emit('locked',true);error.value='';try{for(const r of props.rows){if(r.adoptionId||r.content.supplemental?.length)continue;const v=await api().get<PayChangeImpact>(`/pay-change-requests/${r.id}/impact?month=${props.month}`);if(!current()||rev!==generation)return;if(v.requestId===r.id&&v.revision===r.revision&&v.hash===r.hash&&v.month===props.month)impacts.value={...impacts.value,[r.id]:v};else error.value=x('预估基线过期，请刷新。','Estimate stale; refresh.')}}catch(e){if(rev===generation)error.value=message(e)}finally{if(rev===generation){busy.value=false;emit('locked',false)}}}
</script>
<template><section class="wf-section"><p class="wf-hint">{{x('月份仅限定检索范围，不代表该月实际工资影响；请查看详情预估。每次最多100份，逐项独立处理。','Month limits search scope, not actual wage impact. Review estimates. Up to 100 independent requests per action.')}}</p><div class="wf-toolbar"><label>{{x('排序','Sort')}}<select v-model="sort" :disabled="disabled||busy"><option value="risk">{{x('优先风险提示','Risk first')}}</option><option value="absolute">{{x('标准差额绝对幅度','Absolute standard difference')}}</option><option value="percent">{{x('标准差额比例','Standard difference percent')}}</option></select></label><button :disabled="disabled||busy||!!pending.length||!month||!salaryAccess" @click="estimate">{{x('读取本月影响排序','Estimate month for sorting')}}</button></div><p v-if="error" role="alert">{{error}}</p><div class="wf-table-wrap"><table v-if="rows.length"><thead><tr><th>{{x('选择','Select')}}</th><th>{{x('主体','Subject')}}</th><th>{{x('生效／审批','Effective / approval')}}</th><th>{{x('风险与标准差额','Risk and standard difference')}}</th><th></th></tr></thead><tbody><tr v-for="r in sorted" :key="r.id"><td><input v-if="allowed(r)&&r.status==='submitted'" type="checkbox" :aria-label="x('选择申请 ','Select request ')+r.id" :checked="selected.includes(r.id)" :disabled="disabled||busy||!!pending.length" @change="choose(r.id,($event.target as HTMLInputElement).checked)"></td><td>{{r.content.profile?.employeeName||r.content.beforeProfile?.employeeName||r.content.adoption?.name||r.employeeId}}</td><td>{{r.effectiveDate}} · {{changeState(r.status,english())}}</td><td>{{risks(r).join(' · ')}}<p v-if="r.adoptionId">{{x('仅门店候选；员工金额影响未知，不替换员工方案。','Store candidate only; employee amount impact unknown.')}}</p><p v-else-if="r.content.supplemental?.length">{{x('独立补发；逐项新收入请查看详情，净额待独立批次计算。','Supplemental pay; review individual new gross in details. Net awaits independent calculation.')}}</p><p v-else>{{impacts[r.id]?.standardDifference??x('未知；尚未预估或来源不足','Unknown; not estimated or sources incomplete')}}<span v-if="impacts[r.id]?.standardPercent!=null"> ({{impacts[r.id]?.standardPercent}}%)</span><span v-if="impacts[r.id]?.issues.length"> · {{impacts[r.id]?.issues.map(issue).join(' · ')}}</span></p></td><td><slot name="review" :request="r"/></td></tr></tbody></table></div><section v-if="headOffice"><p>{{x('已选申请','Selected requests')}}: {{selected.length}} / 100</p><label>{{x('批量审批说明','Batch decision note')}}<textarea v-model="note" :disabled="disabled||busy||!!pending.length" maxlength="1000" :aria-label="x('批量审批说明','Batch decision note')"/></label><div class="wf-form-actions"><button :disabled="disabled||busy||!!pending.length||!selected.length||!note.trim()" @click="start('approve')">{{x('批量批准','Approve selected')}}</button><button :disabled="disabled||busy||!!pending.length||!selected.length||!note.trim()" @click="start('reject')">{{x('批量驳回','Reject selected')}}</button><button v-if="pending.length" :disabled="disabled||busy" @click="execute(pending)">{{x('重试未成功项（原命令）','Retry unresolved (same commands)')}}</button><button v-if="pending.length&&!error" :disabled="disabled||busy" @click="pending=[];selected=[]">{{x('结束本轮并重新选择','Finish attempt and select again')}}</button></div><p v-if="pending.length" class="wf-hint">{{x('未成功项保留原修订、哈希、说明和命令；成功项不再提交。基线过期请刷新后重新审核。','Unresolved items retain revision, hash, note and command. Successes are excluded. Refresh stale baselines before a new review.')}}</p></section><ul v-if="results.length" aria-label="batch-results"><li v-for="r in results" :key="r.commandId">{{r.requestId}} · {{r.outcome==='success'?x('成功','Success'):r.outcome==='stale'?x('基线过期','Stale baseline'):x('失败','Failed')}} {{r.errorCode}}<span v-if="r.request?.status==='approved'"> · {{r.request.effectivity==='future'?x('批准待生效','Approved future'):x('已批准','Approved')}}</span></li></ul></section></template>
<style scoped>td{overflow-wrap:anywhere}textarea{max-width:100%;box-sizing:border-box}</style>
